/** Редакционное представление прежних статей. Таблицы считают значения
 * из общих правил; они описывают базовые настройки, не состояние выбранного мира. */
import {RULES,actionEnergyCost} from './evolution.js';
import {SUBSTEPS,DT,ACTION_DURATIONS,DECISION_COST,REPEAT_COST} from './action-timing.js';
import {ENERGY_DEFICIT_FACTOR} from './energy-budget.js';
import {REPRODUCTION_DEFAULTS} from './reproduction.js';
import {SOURCE_CAPACITY_LIMITS} from './food-settings.js';
import {STRUCTURAL_TYPE_LAYOUT} from './structural-brain.js';
import {ENVIRONMENT_RULES} from './environment-settings.js';
import {GATE_INPUTS,GATE_HIDDEN} from './temporal-layout.js';

const number=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:4});
const value=(n,unit='')=>`<span class="guide-value">${number.format(n)}${unit?' '+unit:''}</span>`;
const control=name=>`<code class="guide-control">${name}</code>`;
const link=(id,text)=>`<a href="#wiki-panel-${id}" data-guide-article="${id}">${text}</a>`;
const paragraph=text=>`<p>${text}</p>`;
const table=(caption,columns,rows)=>`<div class="guide-table-wrap"><table class="guide-reference-table"><caption>${caption}</caption><thead><tr>${columns.map(label=>`<th scope="col">${label}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,...cells])=>`<tr><th scope="row">${label}</th>${cells.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const actions=[[0,'Движение'],[6,'Сбор пищи'],[7,'Еда'],[8,'Ожидание'],[10,'Выкладывание пищи']];

export const GUIDE_REFERENCE_TEXT={
 'description38':paragraph(`Геном версии ${value(STRUCTURAL_TYPE_LAYOUT.version)} задаёт наследуемую основу организма. В нём хранятся схема главного блока мозга и исходные веса, свойства ощущений, памяти и обучения. Кодировщик клеток и контроллер внимания тоже наследуются.`)+paragraph(`Начальное устройство мозга основателей задаётся в стартовых условиях. У потомка структура может измениться при ${link('selection','рождении')}; число генов зависит от получившейся схемы.`),
 'description40':paragraph('Жители с разным поведением оставляют разное число потомков. Вместе с этим меняется распространённость наследуемых свойств. Назначенных очков за «правильное» поведение нет.'),
 'description41':paragraph(`Внутри одной родословной могут появляться разные геномы: ${link('genome','мутации')} продолжаются в следующих поколениях.`),
 'description42':paragraph(`Доступность действия зависит от состояния тела и клетки. Направления движения отсчитываются от собственного взгляда жителя. Его ${link('geography','обзор')} охватывает ближайшую окрестность.`),
 'description43':paragraph(`Какое из доступных действий выполнить, решает ${link('brain','мозг')}. Поиск пищи, запасание и перемещения складываются из этих решений.`),
 'description44':paragraph('Мозг получает сведения о видимых клетках и собственном состоянии. На их основе сеть оценивает последствия каждого доступного действия.')+'<ol><li>Кодировщик обрабатывает сведения о клетках.</li><li>Главный блок собирает общую ситуацию и вычисляет оценки <code>Q</code>.</li><li>Оценки превращаются в вероятности, по которым выбирается действие.</li></ol>'+paragraph('Малая сеть внимания проверяет ситуацию между основными решениями и может запросить пересмотр действия.')+`<details class="guide-rules"><summary>Технические детали сети</summary>${paragraph('Скрытые нейроны используют функцию <code>tanh</code>. Выходная оценка <code>Q</code> — прогноз субъективных последствий действия.')}${paragraph(`Сеть внимания получает ${value(GATE_INPUTS,'входов')}, использует скрытый слой размером ${value(GATE_HIDDEN)} и один выход для пересмотра действия. Она наследуется вместе с геномом.`)}</details>`,
 'description45':paragraph(`Во время обучения мозг сравнивает ожидаемые последствия с полученным ощущением и ожидаемым продолжением. Ошибка прогноза меняет личные поправки к весам и смещениям. Наследуемая основа остаётся прежней.`)+paragraph(`Что считается улучшением, зависит от знака чувствительностей к энергии, здоровью и желудку. Поэтому для чтения результата важно различать ${link('research','самочувствие и показатели выживания')}. Алгоритм обучения — <code>Expected SARSA</code> с градиентным следом.`),
 'description47':paragraph(`Личная система координат начинается с <code>(0, 0)</code>, память — с пустых записей. Места, найденные родителем, ребёнку не передаются. Память может работать и при выключенном обучении весов.`)+paragraph('Собственные перемещения учитываются точно. Отдельного энергетического расхода на хранение памяти сейчас нет.'),
 'description48':paragraph('Пищевой источник находится на клетке суши. Источники объединяются в островки; между ними могут находиться одиночные кусты.')+paragraph('Общее число источников задаёт бюджет, который распределяется между группами. Разброс размеров определяет равномерные случайные веса групп. После округления до целых общий бюджет сохраняется.'),
 'description49':paragraph('У каждого островка и одиночного куста свой период восстановления и начальная фаза. Когда наступает срок пополнения:')+'<ul><li>неполный источник получает одну порцию;</li><li>полный источник пропускает пополнение, долг не накапливается.</li></ul>'+paragraph(`Расписание выполняется по сетке времени ${value(DT,'Т')}. При включённой ${link('environment','автоматике среды')} поля показывают текущие параметры и заблокированы. Для ручной настройки автоматику нужно выключить.`),
 'description50':paragraph('Расписание пополнения скрыто от жителя: он узнаёт о пище через наблюдения и память. Быстрое восстановление небольшого числа источников и медленное восстановление большого числа создают разные условия поиска.')+paragraph('При одинаковом seed изменение пищевых настроек сохраняет начальные геномы и позиции жителей.'),
 'description54':paragraph(`В панели ${control('Изменить текущий мир')} можно изменить число источников, период, вместимость или расположение. Допустимая вместимость — от ${value(SOURCE_CAPACITY_LIMITS.min)} до ${value(SOURCE_CAPACITY_LIMITS.max,'порций')}.`)+paragraph('Применение происходит между целыми шагами. Жители, память и родословные продолжают ту же историю; работающий мир продолжает расчёт.'),
 'description55':paragraph('Вместимость задаётся средним и разбросом целых значений. Изменение числа источников или размеров островков может перераспределить их. Сам период можно изменить без переноса источников.')+paragraph('Уже лежащая пища остаётся на своих клетках. Новый источник начинает без дополнительного урожая; уменьшение вместимости не удаляет накопленный избыток. Ручное применение создаёт новое расписание и отменяет оставшиеся события подготовки среды.'),
 'description56':paragraph('Жители обнаруживают перемены при следующих наблюдениях и пересматривают воспоминания. В журнале сохраняются время и итоги вмешательств; на графике они отмечены пунктиром.')+paragraph(`${control('Скачать наблюдения')} выгружает журнал и результаты жизней для анализа.`),
 'description57':paragraph(`${control('Положить')} переносит одну порцию из инвентаря на текущую клетку суши. Действие занимает ${value(ACTION_DURATIONS[10]/SUBSTEPS,'Т')} и расходует ${value(actionEnergyCost(10)*ACTION_DURATIONS[10]/SUBSTEPS,'энергии')}, к которым добавляется ${link('brain','цена решения')}.`)+paragraph(`Выкладывание доступно, пока на клетке меньше ${value(RULES.groundFoodCapacity,'порций')}. Оставленную пищу может подобрать любой житель; назначенной награды за запасание нет.`),
 'description58':paragraph('Вне источника пища сохраняется до сбора и сама не пополняется. Если забрать пищу с полного источника, освободится место для следующего урожая.')+paragraph(`Порог выкладывания ограничивает это действие, а не весь запас клетки. Пища, выросшая или сохранившаяся выше порога при изменении настроек, остаётся доступной.`),
 'description59':paragraph('Продолжительность жизни, причины гибели, число детей и устойчивость населения отвечают на разные вопросы о результате опыта. Самочувствие показывает субъективную оценку состояния, зависящую от чувствительностей генома.'),
 'description60':paragraph(`Скопление возле еды может возникнуть из-за памяти, врождённых склонностей или гибели ушедших жителей. Сравнение режимов памяти и обучения при сопоставимых стартах и нескольких исходных повторах помогает отделить эти причины.`),
 'description61':paragraph(`У ребёнка один родитель, после рождения он действует самостоятельно. Предельный возраст жителя — ${value(RULES.maxAge,'Т')}. Лимит живого населения влияет на возможность начать ${link('selection','роды')}.`),
 'description62':paragraph(`Чтобы продолжить расчёт после закрытия страницы, нужно ${link('saves','сохранить полный мир')}. Результаты опытов и геном служат для анализа и настройки, а состояние текущей жизни хранится в полном сохранении.`),
 'description63':paragraph('Подчёркнутые подписи настроек показывают пояснение при наведении или фокусе с клавиатуры. На телефоне нажми подпись. Закрыть подсказку можно клавишей <kbd>Escape</kbd>.')+paragraph('<a href="./source.html" data-help="guide-code-index">Исходники проекта</a> · <a href="./source.html?file=docs/future-ideas.md" data-help="guide-future-index">Идеи развития</a>'),
 'description64':'Исходники игры, проверки и правила работы с проектом.',
 'description65':paragraph('Житель видит свою клетку и шесть соседних: пищу, наличие источника и деятельность других. Источник заметен даже без лежащей на нём еды; его скрытое расписание не раскрывается.')+paragraph('Вода непроходима. Броды образуют сухие переходы через неё.'),
 'description66':paragraph(`Одна единица времени ${value(1,'Т')} содержит ${value(SUBSTEPS,'подшагов')}. Действие занимает несколько подшагов; результат возникает при завершении.`)+table('Длительности действий',['Действие','Время, Т'],[...actions,[9,'Роды']].map(([id,name])=>[name,value(ACTION_DURATIONS[id]/SUBSTEPS)]))+paragraph('При прерывании уже потраченные время и энергия не возвращаются. Незавершённый переход оставляет жителя на исходном гексе.'),
 'description67':table('Расход на деятельность, без цены решения',['Действие','Энергия за 1 Т'],actions.map(([id,name])=>[name,value(actionEnergyCost(id))]))+paragraph('При сборе порция попадает в инвентарь. После еды она переходит в желудок и постепенно усваивается, пополняя энергию тела.')+table('Питание: значения по умолчанию',['Параметр','Значение'],[
  ['Энергия одной порции',value(RULES.foodEnergy)],['Вместимость инвентаря, порций',value(RULES.inventoryCapacity)],['Вместимость желудка, энергия',value(RULES.stomachCapacity)],['Усвоение одной порции',value(RULES.foodEnergy/RULES.digestionRate,'Т')],
 ])+paragraph('Время усвоения можно отдельно задать для мира или варианта опыта. Если энергия тела уже заполнена, избыток усвоенной энергии теряется.')+paragraph(`Когда энергии не хватает на расход, недостающая единица оплачивается потерей примерно ${value(ENERGY_DEFICIT_FACTOR,'здоровья')}. Нулевой запас сам по себе дополнительного штрафа не добавляет.`),
 'description68':table('Базовые ставки основного мозга',['Причина решения','Энергия'],[['Обычный выбор, пересмотр или физический срыв',value(DECISION_COST)],['Плановый повтор той же деятельности',value(REPEAT_COST)]])+paragraph('Фактическая цена масштабируется объёмом вычислений, включая обучение. У движения повтор определяется по фактическому направлению.')+paragraph('Неоплаченный расход, включая мышление, переводится в потерю здоровья. Малая сеть проверяет ситуацию каждый подшаг: продолжение сохраняет прогресс, новая попытка начинается с нуля.'),
 'description69':table('Пороги начала родов: значения по умолчанию',['Условие','Минимум'],[
  ['Возраст',value(REPRODUCTION_DEFAULTS.maturity,'Т')],['Энергия',value(REPRODUCTION_DEFAULTS.energy)],['Здоровье',value(REPRODUCTION_DEFAULTS.health)],['Интервал после прошлых родов',value(REPRODUCTION_DEFAULTS.birthInterval,'Т')],
 ])+paragraph(`Пороги настраиваются для мира и вариантов опыта. Во время родов другие действия и добровольный пересмотр заблокированы.`)+paragraph(`При завершении родитель передаёт ${value(RULES.newbornEnergy,'энергии')} ребёнку и расходует ${value(RULES.birthCost-RULES.newbornEnergy)} на сами роды: всего списывается ${value(RULES.birthCost)}. Гибель до завершения отменяет рождение.`)+paragraph('Лимит населения проверяется при начале. Уже начатые роды могут завершиться сверх этого лимита.'),
 'description70':paragraph(`Схема мозга допускает связи вперёд, в том числе прямые вход→выход и пропуски слоёв. Нейроны, слои и связи могут измениться при наследовании. Отдельный наследуемый ген задаёт вероятность структурной мутации.`),
 'description71':paragraph('Краткая память получает видимые факты каждый подшаг. Закрепление учитывает время наблюдения: простое увеличение частоты записи не усиливает память.')+paragraph('Само обнаружение источника не помещает его в долгую память автоматически; важны условия закрепления опыта.'),
 'wiki-start':paragraph(`Нажми ${control('Наблюдать')} во вкладке ${control('Мир')}, чтобы запустить время. Та же кнопка переключается в ${control('Пауза')} и доступна из остальных разделов. ${control('Подшаг')} продвигает мир на ${value(DT,'Т')} и оставляет его на паузе.`)+paragraph('Темп управляет скоростью наблюдения. Нажатие на жителя открывает его состояние и решения. Запуск отдельных опытов приостанавливает основной мир.')+paragraph(`Стартовые условия применяются после ${control('Начать новый опыт')}. Перед заменой мира используй ${control('Сохранить мир')}.`),
 'wiki-saves':paragraph(`${control('Сохранить мир')} скачивает состояние, с которым можно продолжить расчёт: жители, память и обучение, действия, пища и расписание среды, история и состояние случайности сохраняются вместе.`)+paragraph(`${control('Загрузить мир')} проверяет файл и открывает его на паузе. Ошибка загрузки или отмена выбора сохраняют прежний мир.`)+table('Какой файл выбрать',['Файл','Назначение'],[['Полный мир','Продолжить остановленный расчёт'],['Геном','Задать наследуемую основу основателей'],['Результаты опыта','Анализировать завершённые или прерванные запуски'],['План опыта','Повторить настройки и сочетания вариантов']])+paragraph('Автосохранения нет; перед закрытием страницы сохрани нужный мир вручную.'),
 'wiki-checks':paragraph(`Во вкладке ${control('Опыты')} раздел ${control('Проверки механизмов')} запускает доступные проверки на твоём устройстве. Проверки поведения, интерфейса и сохранений рассматривают разные части программы.`)+paragraph('Фактически выполненный состав записан в протоколе выпуска. Чтобы найти проверку конкретного механизма, раскрой блок «Где это в коде» в соответствующей статье.'),
 'wiki-environment':paragraph('Автоматика постепенно переводит пищевую среду к заданным условиям, затем поддерживает случайные изменения около них.')+`<ol><li>Первые ${value(ENVIRONMENT_RULES.preparationSteps)} событий приближают число источников и средний период к целевым значениям.</li><li>После подготовки параметры колеблются около целей. Коррекция возвращает ${value(ENVIRONMENT_RULES.returnFraction*100,'%')} отклонения за событие.</li></ol>`+paragraph('Островки могут перемещаться целиком, менять размер и число. Рост идёт по краям; если рядом не хватает суши, остаток бюджета становится одиночными кустами. Вода и занятые источниками клетки исключаются из переноса.')+table('Перемещения за событие',['Что перемещается','Дальность'],[['Островок целиком',`От ${value(ENVIRONMENT_RULES.islandRelocationMinimum)} до ${value(ENVIRONMENT_RULES.islandRelocationRadius,'гексов')}`],[`${value(ENVIRONMENT_RULES.relocationFraction*100,'%')} одиночных кустов`,`До ${value(ENVIRONMENT_RULES.relocationRadius,'гексов')}`]])+paragraph(`Для островка проверяется до ${value(ENVIRONMENT_RULES.islandRelocationAttempts)} случайных смещений. Если подходящего места нет, группа остаётся на месте. Форма островка при переносе сохраняется.`)+paragraph('Границы выработки относятся к потенциальному производству пищи. Сначала меняется число источников, затем при достижении его предела — периоды. Уже лежащая пища сохраняется; ручное вмешательство отменяет оставшуюся подготовку.'),
 'wiki-statistics-refresh':paragraph(`Во время моделирования график и сводка сохраняют последний готовый результат, пока в фоне считается следующий. Шаг показанного отчёта указан над графиками.`)+paragraph('Обычные значения округляются до одного знака после запятой; малые величины и стоимость мышления показываются точнее. Прочерк означает отсутствие данных.'),
};
